//! Offline Stage 10 laboratory profile. Not a Sigstore/Fulcio verifier.
use crate::{
    cbor::canonical::encode_json,
    error::VerifyError,
    hash::{blake3_256, sha256},
};
use ed25519_dalek::{Signature, VerifyingKey};
use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::collections::HashSet;

pub const PROFILE: &str = "arkhe-gguf-lab@1";
pub const MAX_ARTIFACT_BYTES: usize = 16 * 1024 * 1024;

fn reject(gate: u8, reason: &str) -> VerifyError {
    VerifyError::VerificationFailed(format!("gate {gate}: {reason}"))
}

struct Reader<'a> {
    bytes: &'a [u8],
    offset: usize,
}
impl<'a> Reader<'a> {
    fn take(&mut self, count: usize) -> Result<&'a [u8], VerifyError> {
        let end = self
            .offset
            .checked_add(count)
            .ok_or_else(|| reject(1, "offset overflow"))?;
        let bytes = self
            .bytes
            .get(self.offset..end)
            .ok_or_else(|| reject(1, "truncated GGUF"))?;
        self.offset = end;
        Ok(bytes)
    }
    fn u32(&mut self) -> Result<u32, VerifyError> {
        Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))
    }
    fn u64(&mut self) -> Result<u64, VerifyError> {
        Ok(u64::from_le_bytes(self.take(8)?.try_into().unwrap()))
    }
    fn text(&mut self) -> Result<String, VerifyError> {
        let count = self.u64()?;
        if count > 4096 {
            return Err(reject(1, "string limit exceeded"));
        }
        let text = std::str::from_utf8(self.take(count as usize)?)
            .map_err(|_| reject(1, "invalid UTF-8"))?;
        if text.is_empty() || text.chars().any(char::is_control) {
            return Err(reject(1, "empty string or control character"));
        }
        Ok(text.into())
    }
}

/// Strict little-endian v3 subset: string metadata, uint32 alignment, F32 tensors.
/// No model is loaded and no metadata/template is executed.
pub fn inspect(bytes: &[u8]) -> Result<Value, VerifyError> {
    if bytes.len() > MAX_ARTIFACT_BYTES {
        return Err(reject(1, "artifact limit exceeded"));
    }
    let mut r = Reader { bytes, offset: 0 };
    if r.take(4)? != b"GGUF" || r.u32()? != 3 {
        return Err(reject(1, "expected GGUF v3 little-endian"));
    }
    let tensors = r.u64()?;
    let entries = r.u64()?;
    if tensors == 0 || tensors > 256 || entries > 128 {
        return Err(reject(1, "tensor/metadata count outside profile"));
    }
    let mut metadata = Map::new();
    let mut alignment = 32usize;
    for _ in 0..entries {
        let name = r.text()?;
        if name.len() > 128
            || !name
                .bytes()
                .all(|c| c.is_ascii_alphanumeric() || b"._".contains(&c))
        {
            return Err(reject(1, "invalid metadata key"));
        }
        let value_type = r.u32()?;
        let value = if name == "general.alignment" && value_type == 4 {
            alignment = r.u32()? as usize;
            if alignment > 4096 || !alignment.is_power_of_two() {
                return Err(reject(1, "invalid alignment"));
            }
            json!(alignment)
        } else if value_type == 8 && name != "general.alignment" {
            json!(r.text()?)
        } else {
            return Err(reject(1, "unsupported metadata type"));
        };
        if metadata.insert(name, value).is_some() {
            return Err(reject(1, "duplicate metadata key"));
        }
    }
    if !metadata
        .get("general.architecture")
        .is_some_and(Value::is_string)
    {
        return Err(reject(1, "missing architecture"));
    }
    let mut names = HashSet::new();
    let mut ranges = Vec::new();
    for _ in 0..tensors {
        if !names.insert(r.text()?) {
            return Err(reject(1, "duplicate tensor name"));
        }
        let dimensions = r.u32()?;
        if !(1..=4).contains(&dimensions) {
            return Err(reject(1, "invalid tensor dimension count"));
        }
        let mut size = 4u64;
        for _ in 0..dimensions {
            let dimension = r.u64()?;
            if dimension == 0 {
                return Err(reject(1, "zero tensor dimension"));
            }
            size = size
                .checked_mul(dimension)
                .ok_or_else(|| reject(1, "tensor size overflow"))?;
        }
        if r.u32()? != 0 {
            return Err(reject(1, "only F32 tensors supported"));
        }
        let offset = r.u64()?;
        if offset % alignment as u64 != 0 {
            return Err(reject(1, "unaligned tensor"));
        }
        let end = offset
            .checked_add(size)
            .ok_or_else(|| reject(1, "tensor offset overflow"))?;
        ranges.push((offset, end));
    }
    let start = r.offset.div_ceil(alignment) * alignment;
    if start > bytes.len() || bytes[r.offset..start].iter().any(|b| *b != 0) {
        return Err(reject(1, "invalid padding"));
    }
    ranges.sort_unstable();
    let mut end = 0;
    for (offset, next) in ranges {
        if offset < end || next > (bytes.len() - start) as u64 {
            return Err(reject(1, "overlapping or truncated tensor"));
        }
        end = next;
    }
    if end != (bytes.len() - start) as u64 {
        return Err(reject(1, "unexpected trailing data"));
    }
    Ok(Value::Object(metadata))
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Statement {
    pub profile: String,
    pub builder_id: String,
    pub artifact_sha256: String,
    pub artifact_blake3: String,
    pub metadata_sha256: String,
}

pub fn statement(bytes: &[u8], builder_id: String) -> Result<Statement, VerifyError> {
    let metadata = inspect(bytes)?;
    Ok(Statement {
        profile: PROFILE.into(),
        builder_id,
        artifact_sha256: hex::encode(sha256(bytes)),
        artifact_blake3: hex::encode(blake3_256(bytes)),
        metadata_sha256: hex::encode(sha256(&super::canonical::canonicalize_metadata(&metadata)?)),
    })
}

pub fn statement_bytes(statement: &Statement) -> Result<Vec<u8>, VerifyError> {
    let mut bytes = b"ARKHE:GGUF:PROVENANCE:v1\0".to_vec();
    bytes.extend(encode_json(
        &serde_json::to_value(statement).map_err(|_| reject(3, "invalid statement"))?,
    )?);
    Ok(bytes)
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Checkpoint {
    pub log_id: String,
    pub tree_size: u64,
    pub root_hex: String,
    pub issued_at: u64,
    pub signature_hex: String,
}
pub fn checkpoint_bytes(checkpoint: &Checkpoint) -> Result<Vec<u8>, VerifyError> {
    let mut bytes = b"ARKHE:GGUF:LOG:v1\0".to_vec();
    bytes.extend(encode_json(
        &json!({"log_id": checkpoint.log_id, "tree_size": checkpoint.tree_size,
        "root_hex": checkpoint.root_hex, "issued_at": checkpoint.issued_at}),
    )?);
    Ok(bytes)
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Bundle {
    pub statement: Statement,
    pub builder_signature_hex: String,
    pub checkpoint: Checkpoint,
    pub leaf_index: u64,
    pub inclusion_path: Vec<String>,
}

/// Must arrive through an independent trusted channel, never from the bundle.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Trust {
    pub builder_id: String,
    pub builder_public_key_hex: String,
    pub log_id: String,
    pub log_public_key_hex: String,
    pub minimum_tree_size: u64,
    pub earliest_issued_at: u64,
    pub latest_issued_at: u64,
}

fn digest(value: &str, gate: u8) -> Result<[u8; 32], VerifyError> {
    hex::decode(value)
        .map_err(|_| reject(gate, "invalid hex"))?
        .try_into()
        .map_err(|_| reject(gate, "expected 32 bytes"))
}
fn signature(public: &str, bytes: &[u8], sig: &str, gate: u8) -> Result<(), VerifyError> {
    let key = VerifyingKey::from_bytes(&digest(public, gate)?)
        .map_err(|_| reject(gate, "invalid key"))?;
    if key.is_weak() {
        return Err(reject(gate, "weak key"));
    }
    let raw = hex::decode(sig).map_err(|_| reject(gate, "invalid signature hex"))?;
    let sig = Signature::from_slice(&raw).map_err(|_| reject(gate, "invalid signature length"))?;
    key.verify_strict(bytes, &sig)
        .map_err(|_| reject(gate, "signature rejected"))
}

/// The leaf binds both the signed statement and its builder signature.
pub fn log_leaf(bundle: &Bundle) -> Result<Vec<u8>, VerifyError> {
    encode_json(
        &json!({"statement": bundle.statement, "builder_signature_hex": bundle.builder_signature_hex}),
    )
}
pub fn leaf_hash(leaf: &[u8]) -> [u8; 32] {
    sha256(&[&[0u8][..], leaf].concat())
}
pub fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
    sha256(&[&[1u8][..], left, right].concat())
}

/// RFC 6962 section 2.1.1, including unbalanced trees and exact path consumption.
pub fn verify_inclusion(
    leaf: &[u8],
    index: u64,
    size: u64,
    path: &[[u8; 32]],
    root: [u8; 32],
) -> Result<(), VerifyError> {
    if size == 0 || index >= size || path.len() > 64 {
        return Err(reject(4, "invalid inclusion bounds"));
    }
    let (mut position, mut last) = (index, size - 1);
    let mut hash = leaf_hash(leaf);
    for sibling in path {
        if last == 0 {
            return Err(reject(4, "excess inclusion nodes"));
        }
        if position & 1 == 1 || position == last {
            hash = node_hash(sibling, &hash);
            while position != 0 && position & 1 == 0 {
                position >>= 1;
                last >>= 1;
            }
        } else {
            hash = node_hash(&hash, sibling);
        }
        position >>= 1;
        last >>= 1;
    }
    if last != 0 || hash != root {
        return Err(reject(4, "inclusion proof rejected"));
    }
    Ok(())
}

#[derive(Debug, Serialize)]
pub struct Report {
    pub profile: String,
    pub gates_passed: [String; 4],
    pub artifact_sha256: String,
    pub artifact_blake3: String,
    pub metadata_sha256: String,
    pub builder_id: String,
    pub log_id: String,
    pub tree_size: u64,
}

pub fn verify(bytes: &[u8], bundle: &Bundle, trust: &Trust) -> Result<Report, VerifyError> {
    let actual = statement(bytes, trust.builder_id.clone())?;
    let s = &bundle.statement;
    if s.profile != PROFILE {
        return Err(reject(2, "unsupported profile"));
    }
    if s.artifact_sha256 != actual.artifact_sha256
        || s.artifact_blake3 != actual.artifact_blake3
        || s.metadata_sha256 != actual.metadata_sha256
    {
        return Err(reject(2, "digest mismatch"));
    }
    if trust.builder_id.is_empty() || s.builder_id != trust.builder_id {
        return Err(reject(3, "builder identity rejected"));
    }
    signature(
        &trust.builder_public_key_hex,
        &statement_bytes(s)?,
        &bundle.builder_signature_hex,
        3,
    )?;
    let cp = &bundle.checkpoint;
    if trust.log_id.is_empty()
        || cp.log_id != trust.log_id
        || trust.minimum_tree_size == 0
        || cp.tree_size < trust.minimum_tree_size
        || trust.earliest_issued_at > trust.latest_issued_at
        || cp.issued_at < trust.earliest_issued_at
        || cp.issued_at > trust.latest_issued_at
    {
        return Err(reject(4, "checkpoint trust bounds rejected"));
    }
    signature(
        &trust.log_public_key_hex,
        &checkpoint_bytes(cp)?,
        &cp.signature_hex,
        4,
    )?;
    let path = bundle
        .inclusion_path
        .iter()
        .map(|p| digest(p, 4))
        .collect::<Result<Vec<_>, _>>()?;
    verify_inclusion(
        &log_leaf(bundle)?,
        bundle.leaf_index,
        cp.tree_size,
        &path,
        digest(&cp.root_hex, 4)?,
    )?;
    Ok(Report {
        profile: PROFILE.into(),
        gates_passed: [
            "gguf_subset",
            "dual_digest",
            "pinned_builder_signature",
            "rfc6962_local_log",
        ]
        .map(String::from),
        artifact_sha256: actual.artifact_sha256,
        artifact_blake3: actual.artifact_blake3,
        metadata_sha256: actual.metadata_sha256,
        builder_id: trust.builder_id.clone(),
        log_id: cp.log_id.clone(),
        tree_size: cp.tree_size,
    })
}

//! Synthetic credential evidence PoC. Does not validate CIN, VIO or government identity.
use crate::{
    error::VerifyError,
    hash::blake3_256,
    mmr::{verify_proof, ProofStep},
};
use ed25519_dalek::{Signature, VerifyingKey};
use serde::{Deserialize, Serialize};
const PROFILE: &str = "arkhe-gov-synthetic-v1";
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Evidence {
    pub profile: String,
    pub jurisdiction: String,
    pub credential_type: String,
    pub credential_digest: [u8; 32],
    pub verifier: String,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Bundle {
    pub evidence: Evidence,
    pub leaf_index: u32,
    pub leaf_count: u32,
    pub proof: Vec<ProofStep>,
    pub checkpoint_root: [u8; 32],
    pub checkpoint_signature_hex: String,
}
fn invalid(message: &str) -> VerifyError {
    VerifyError::InvalidInput(message.into())
}
pub fn credential_digest(bytes: &[u8]) -> [u8; 32] {
    let mut input = b"AKG:GOV:SYNTHETIC-CREDENTIAL:v1\0".to_vec();
    input.extend_from_slice(bytes);
    blake3_256(&input)
}
pub fn evidence_leaf(record: &Evidence) -> Result<Vec<u8>, VerifyError> {
    if record.profile != PROFILE
        || record.jurisdiction != "BR"
        || record.credential_type != "CIN_SYNTHETIC"
        || record.verifier != "fixture-only-not-vio"
    {
        return Err(invalid("unsupported synthetic evidence profile"));
    }
    let mut bytes = b"AKG:GOV:SYNTHETIC-EVIDENCE:v1\0".to_vec();
    bytes.extend_from_slice(&record.credential_digest);
    Ok(blake3_256(&bytes).to_vec())
}
pub fn checkpoint_payload(root: &[u8; 32], count: u32) -> Vec<u8> {
    let mut bytes = b"AKG:GOV:SYNTHETIC-CHECKPOINT:v1\0".to_vec();
    bytes.extend_from_slice(&count.to_be_bytes());
    bytes.extend_from_slice(root);
    bytes
}
/// Trust key is supplied separately, never selected from the untrusted bundle.
/// Credential bytes are caller-local and are never retained by this pure verifier.
pub fn verify(bytes: &[u8], bundle: &Bundle, trusted_key: &[u8; 32]) -> Result<bool, VerifyError> {
    if bytes.is_empty()
        || bytes.len() > 32768
        || bundle.leaf_count != 4
        || bundle.leaf_index >= 4
        || bundle.proof.len() != 2
    {
        return Err(invalid("invalid four-leaf PoC shape"));
    }
    let mut index = bundle.leaf_index;
    for step in &bundle.proof {
        let direction = if index.is_multiple_of(2) {
            "right"
        } else {
            "left"
        };
        if step.kind != "node" || step.direction != direction {
            return Err(invalid("proof position mismatch"));
        }
        index /= 2;
    }
    let leaf = evidence_leaf(&bundle.evidence)?;
    if credential_digest(bytes) != bundle.evidence.credential_digest {
        return Ok(false);
    }
    let key = VerifyingKey::from_bytes(trusted_key).map_err(|_| invalid("invalid trusted key"))?;
    let signature = hex::decode(&bundle.checkpoint_signature_hex)
        .map_err(|_| invalid("invalid signature encoding"))?;
    let signature =
        Signature::from_slice(&signature).map_err(|_| invalid("invalid signature length"))?;
    if key
        .verify_strict(
            &checkpoint_payload(&bundle.checkpoint_root, bundle.leaf_count),
            &signature,
        )
        .is_err()
    {
        return Ok(false);
    }
    verify_proof(&leaf, 4, &bundle.proof, &bundle.checkpoint_root)
}

//! Authenticated lifecycle receipts from a verifier. Native government validation is a separate adapter.
use crate::{cbor::canonical::encode_json, error::VerifyError};
use ed25519_dalek::{Signature, VerifyingKey};
use serde::{Deserialize, Serialize};
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum CredentialProfile {
    IcpBrasilCms,
    CinVio,
}
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum RevocationState {
    Good,
    Revoked,
    Unknown,
}
/// Only the synthetic qualification exists until native bridges are independently qualified.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Qualification {
    SyntheticReceipt,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LifecycleReceipt {
    pub version: u16,
    pub qualification: Qualification,
    pub credential_profile: CredentialProfile,
    pub credential_digest: [u8; 32],
    pub issuer_key_digest: [u8; 32],
    pub policy_digest: [u8; 32],
    pub validation_material_digest: [u8; 32],
    pub audience: String,
    pub challenge: [u8; 32],
    pub valid_from: i64,
    pub expires_at: i64,
    pub verified_at: i64,
    pub revocation: RevocationState,
    pub status_this_update: i64,
    pub status_next_update: i64,
    pub signature_hex: String,
}
impl LifecycleReceipt {
    pub fn signing_bytes(&self) -> Result<Vec<u8>, VerifyError> {
        let mut value = serde_json::to_value(self)
            .map_err(|_| VerifyError::InvalidInput("invalid lifecycle".into()))?;
        value.as_object_mut().unwrap().remove("signature_hex");
        let mut bytes = b"AKG:GOV:LIFECYCLE-RECEIPT:v1\0".to_vec();
        bytes.extend(encode_json(&value)?);
        Ok(bytes)
    }
}
/// Trusted host inputs, not fields copied from the untrusted credential.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LifecycleTrust {
    pub verifier_key: [u8; 32],
    pub credential_profile: CredentialProfile,
    pub issuer_key_digest: [u8; 32],
    pub policy_digest: [u8; 32],
    pub max_receipt_age: i64,
    pub max_status_age: i64,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LifecycleContext {
    pub credential_digest: [u8; 32],
    pub audience: String,
    pub challenge: [u8; 32],
    /// Trusted Unix seconds. No clock is fetched inside the pure verifier.
    pub now: i64,
}
pub fn verify(
    receipt: &LifecycleReceipt,
    trust: &LifecycleTrust,
    context: &LifecycleContext,
) -> Result<bool, VerifyError> {
    let nonzero = |value: &[u8; 32]| *value != [0; 32];
    if context.now < 0
        || context.audience.is_empty()
        || context.audience.len() > 256
        || !nonzero(&context.challenge)
        || !nonzero(&context.credential_digest)
        || !nonzero(&trust.issuer_key_digest)
        || !nonzero(&trust.policy_digest)
        || trust.max_receipt_age <= 0
        || trust.max_status_age <= 0
        || receipt.signature_hex.len() != 128
    {
        return Err(VerifyError::InvalidInput(
            "invalid lifecycle trust/context/encoding".into(),
        ));
    }
    if receipt.version != 1
        || receipt.credential_profile != trust.credential_profile
        || receipt.credential_digest != context.credential_digest
        || receipt.issuer_key_digest != trust.issuer_key_digest
        || receipt.policy_digest != trust.policy_digest
        || !nonzero(&receipt.validation_material_digest)
        || receipt.audience != context.audience
        || receipt.challenge != context.challenge
        || receipt.valid_from < 0
        || receipt.valid_from > context.now
        || receipt.expires_at <= context.now
        || receipt.verified_at < receipt.valid_from
        || receipt.verified_at > context.now
        || context.now.saturating_sub(receipt.verified_at) > trust.max_receipt_age
        || receipt.revocation != RevocationState::Good
        || receipt.status_this_update < 0
        || receipt.status_this_update > receipt.verified_at
        || receipt.status_next_update <= context.now
        || receipt.status_next_update <= receipt.status_this_update
        || context.now.saturating_sub(receipt.status_this_update) > trust.max_status_age
    {
        return Ok(false);
    }
    let key = VerifyingKey::from_bytes(&trust.verifier_key)
        .map_err(|_| VerifyError::InvalidInput("invalid lifecycle key".into()))?;
    if key.is_weak() {
        return Ok(false);
    }
    let raw = hex::decode(&receipt.signature_hex)
        .map_err(|_| VerifyError::InvalidInput("invalid lifecycle signature".into()))?;
    let signature = Signature::from_slice(&raw)
        .map_err(|_| VerifyError::InvalidInput("invalid lifecycle signature length".into()))?;
    Ok(key
        .verify_strict(&receipt.signing_bytes()?, &signature)
        .is_ok())
}

use sha2::{Digest, Sha256};

pub fn blake3_256(data: &[u8]) -> [u8; 32] {
    *blake3::hash(data).as_bytes()
}

pub fn sha256(data: &[u8]) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update(data);
    h.finalize().into()
}

